/* Atlético Madrid DNA — rojiblanco stripes, colchonero navy */
.theme-atletico-madrid {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.973 0 0);
  --surface-2: oklch(0.943 0 0);
  --fg: oklch(0.191 0 0);
  --fg-muted: oklch(0.485 0 0);
  --accent: oklch(0.558 0.189 30.4);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.324 0.092 273.6);
  --line: oklch(0.922 0 0);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.558 0.189 30.4);
  --radius: 0.375rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Saira", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.12em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-atletico-madrid h1,
.theme-atletico-madrid h2,
.theme-atletico-madrid h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-atletico-madrid { --font-ui: var(--font-display); }
.theme-atletico-madrid h1, .theme-atletico-madrid h2 { text-transform: uppercase; font-weight: 700; }
.theme-atletico-madrid h1::after { content: ""; display: block; height: 4px; width: 5rem; margin-top: 0.6rem; background: var(--accent-2); }
.theme-atletico-madrid button { text-transform: uppercase; letter-spacing: 0.06em; font-weight: 600; }

.theme-atletico-madrid { background-image: repeating-linear-gradient(90deg, color-mix(in oklab, var(--accent) 8%, transparent) 0 60px, transparent 60px 120px); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
